import{_ as a,c as e,o as r,ag as n}from"./chunks/framework.C7v41-tM.js";const _=JSON.parse('{"title":"RAG 切分：先保住完整证据，再调长度","description":"","frontmatter":{},"headers":[],"relativePath":"technical/rag-chunking-practice.md","filePath":"technical/rag-chunking-practice.md","lastUpdated":null}'),d={name:"technical/rag-chunking-practice.md"};function i(h,t,o,c,l,p){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="rag-切分-先保住完整证据-再调长度" tabindex="-1">RAG 切分：先保住完整证据，再调长度 <a class="header-anchor" href="#rag-切分-先保住完整证据-再调长度" aria-label="Permalink to &quot;RAG 切分：先保住完整证据，再调长度&quot;">​</a></h1><p>切分参数的目标是让需要的证据能被一起找到，而不是把所有文档切成一样长。本文讨论调试过程；<a href="https://github.com/lixudong1649/jdp-wiki/blob/main/content/terms/rag.md" target="_blank" rel="noreferrer">RAG 的概念解释</a> 由 Wiki 维护。</p><h2 id="用一个退款条款做检查" tabindex="-1">用一个退款条款做检查 <a class="header-anchor" href="#用一个退款条款做检查" aria-label="Permalink to &quot;用一个退款条款做检查&quot;">​</a></h2><p>假设原文是：“签收七天内可以申请退款，仅适用于未拆封商品。”这是教学示例，不是任何公司的实际规则。</p><p>如果两个条件被切进不同片段，召回“七天内”仍可能让回答漏掉“未拆封”。因此先观察切分后的文本，再观察召回，最后观察生成回答；不能只看最终答案是否流畅。</p><h2 id="从结构切分起步" tabindex="-1">从结构切分起步 <a class="header-anchor" href="#从结构切分起步" aria-label="Permalink to &quot;从结构切分起步&quot;">​</a></h2><p>先按标题、段落和条款切分，超长单元再细分。表格保留表头、单位与行列关系；代码尽量保留函数边界。固定字符长度可以控制大小，但字符不是 Token，没有通用的最佳长度或重叠比例。</p><table tabindex="0"><thead><tr><th>观察到的问题</th><th>优先检查</th><th>可以比较的调整</th></tr></thead><tbody><tr><td>条件被截断</td><td>片段正文和边界</td><td>保留完整条款、读相邻片段</td></tr><tr><td>相关词很多但答案不相关</td><td>片段是否混合多个主题</td><td>缩小结构单元</td></tr><tr><td>上下文重复</td><td>重叠范围及返回结果</td><td>合并相邻片段或去重</td></tr><tr><td>表格内容无法解释</td><td>解析是否保留表头与单位</td><td>先修解析，重叠不能补回丢失内容</td></tr></tbody></table><h2 id="一次只改变一个因素" tabindex="-1">一次只改变一个因素 <a class="header-anchor" href="#一次只改变一个因素" aria-label="Permalink to &quot;一次只改变一个因素&quot;">​</a></h2><p>固定问题、所需证据和检索／生成模型，比较切分变化。记录证据覆盖、片段数、上下文重复和费用，不能用教学演示分数直接选择生产参数。</p><p>每段至少关联文档、位置、标题路径、版本和权限。重新切分后同步更新索引，引用应能回到对应版本。</p><p>参考：<a href="https://reference.langchain.com/python/langchain-text-splitters/base/TextSplitter" target="_blank" rel="noreferrer">LangChain TextSplitter</a>。本文为工程建议，整理与来源复核：2026-10-14。</p>',12)])])}const g=a(d,[["render",i]]);export{_ as __pageData,g as default};
